Evaluate the JavaScript Space Invaders game implementation on a scale of 0-10 points:

**Game Completeness (4 points)**: Does it implement all core Space Invaders features - player movement, shooting, enemy formations, collision detection, and proper win/lose conditions?

**Gameplay Quality (3 points)**: Are the controls responsive? Is the difficulty balanced? Do enemies move in proper formation and shoot back? Are collision mechanics accurate?

**Visual & Audio Feedback (2 points)**: Does it include clear sprites, smooth animations, explosion effects, and score display? Is the visual feedback satisfying?

**Performance & Code Quality (1 point)**: Does it run smoothly at 60 FPS with efficient game loop and well-structured code?

Solution A: function createSpaceInvaders(canvasId){const canvas=document.getElementById(canvasId);if(!canvas)return;const ctx=canvas.getContext('2d');const W=canvas.width;const H=canvas.height;let lastTime=0;let animationId;let level=1;let score=0;let gameOver=false;let win=false;const keys={};window.addEventListener('keydown',e=>keys[e.code]=true);window.addEventListener('keyup',e=>keys[e.code]=false);const player={w:40,h:20,x:W/2-20,y:H-30,speed:200,cooldown:0};const playerBullets=[];const enemyBullets=[];let enemies=[];let enemyDir=1;let enemySpeed=30;let enemyDescend=20;let enemyFireTimer=0;let explosions=[];function initEnemies(){enemies=[];const rows=5;const cols=10;const ew=30;const eh=20;const gapX=10;const gapY=15;const offsetX=(W-(cols*ew+ (cols-1)*gapX))/2;const offsetY=30;for(let r=0;r<rows;r++){for(let c=0;c<cols;c++){enemies.push({w:ew,h:eh,x:offsetX+c*(ew+gapX),y:offsetY+r*(eh+gapY)});}}enemyDir=1;enemySpeed=30+level*5;enemyFireTimer=0;}function update(dt){if(gameOver)return;player.cooldown-=dt;if(keys['ArrowLeft'])player.x-=player.speed*dt;if(keys['ArrowRight'])player.x+=player.speed*dt;player.x=Math.max(0,Math.min(W-player.w,player.x));if(keys['Space'] && player.cooldown<=0){playerBullets.push({x:player.x+player.w/2-2,y:player.y,w:4,h:10,dy:-300});player.cooldown=0.3;}playerBullets.forEach(b=>b.y+=b.dy*dt);enemyBullets.forEach(b=>b.y+=b.dy*dt);playerBullets.splice(0,playerBullets.findIndex(b=>b.y+b.h<0)+1);enemyBullets.splice(0,enemyBullets.findIndex(b=>b.y>H)+1);let blockLeft=W,blockRight=0,blockBottom=0;enemies.forEach(e=>{blockLeft=Math.min(blockLeft,e.x);blockRight=Math.max(blockRight,e.x+e.w);blockBottom=Math.max(blockBottom,e.y+e.h);});if(blockRight+enemyDir*enemySpeed*dt>W||blockLeft+enemyDir*enemySpeed*dt<0){enemyDir*=-1;enemies.forEach(e=>e.y+=enemyDescend);}enemies.forEach(e=>e.x+=enemyDir*enemySpeed*dt);enemyFireTimer+=dt;if(enemyFireTimer>1){enemyFireTimer=0;if(enemies.length){const shooter=enemies[Math.floor(Math.random()*enemies.length)];enemyBullets.push({x:shooter.x+shooter.w/2-2,y:shooter.y+shooter.h,w:4,h:10,dy:200});}} // collisions player bullets vs enemies for(let i=playerBullets.length-1;i>=0;i--){let b=playerBullets[i];let hit=-1;for(let j=0;j<enemies.length;j++){let e=enemies[j];if(b.x<b.x+ b.w && b.x+b.w>e.x && b.y<b.y+b.h && b.y+b.h>e.y){hit=j;break;}}if(hit>=0){explosions.push({x:enemies[hit].x+enemies[hit].w/2,y:enemies[hit].y+enemies[hit].h/2,life:0.3});enemies.splice(hit,1);playerBullets.splice(i,1);score+=10;}} // enemy bullets vs player for(let i=enemyBullets.length-1;i>=0;i--){let b=enemyBullets[i];if(b.x<b.x+b.w && b.x+b.w>player.x && b.y<b.y+b.h && b.y+b.h>player.y){explosions.push({x:player.x+player.w/2,y:player.y+player.h/2,life:0.5});gameOver=true;break;}} // enemy reach bottom if(blockBottom>=player.y){gameOver=true;} // update explosions for(let i=explosions.length-1;i>=0;i--){explosions[i].life-=dt;if(explosions[i].life<=0)explosions.splice(i,1);} if(!gameOver && enemies.length===0){level++;initEnemies();} }function draw(){ctx.clearRect(0,0,W,H); // player ctx.fillStyle='white';ctx.fillRect(player.x,player.y,player.w,player.h); // player bullets ctx.fillStyle='lime';playerBullets.forEach(b=>ctx.fillRect(b.x,b.y,b.w,b.h)); // enemies ctx.fillStyle='red';enemies.forEach(e=>ctx.fillRect(e.x,e.y,e.w,e.h)); // enemy bullets ctx.fillStyle='orange';enemyBullets.forEach(b=>ctx.fillRect(b.x,b.y,b.w,b.h)); // explosions ctx.fillStyle='yellow';explosions.forEach(p=>{ctx.beginPath();ctx.arc(p.x,p.y,15* (p.life/0.5),0,2*Math.PI);ctx.fill();}); // UI ctx.fillStyle='white';ctx.font='16px monospace';ctx.fillText('Score: '+score,10,20);ctx.fillText('Level: '+level,10,40); if(gameOver){ctx.fillStyle='white';ctx.font='48px monospace';ctx.fillText('GAME OVER',W/2-150,H/2); } }function loop(timestamp){let dt=(timestamp-lastTime)/1000;lastTime=timestamp;update(dt);draw();if(!gameOver)animationId=requestAnimationFrame(loop);}initEnemies();requestAnimationFrame(loop);}

Solution B: function playSpaceInvaders(canvasId) {  
    const canvas = document.getElementById(canvasId);  
    const ctx = canvas.getContext('2d');  

    const WIDTH = canvas.width;  
    const HEIGHT = canvas.height;  

    const KEY = { LEFT: 37, RIGHT: 39, SPACE: 32 };  
    const keys = {};  

    window.addEventListener('keydown', e => { keys[e.keyCode] = true; });  
    window.addEventListener('keyup', e => { keys[e.keyCode] = false; });  

    let score = 0;  
    let level = 1;  
    let gameOver = false;  

    // Player  
    const player = {  
        x: WIDTH / 2,  
        y: HEIGHT - 40,  
        w: 30,  
        h: 20,  
        speed: 5,  
        bullets: [],  
        fireCooldown: 0  
    };  

    // Enemy grid
    const enemy = {  
        rows: 3,  
        cols: 7,  
        w: 32,  
        h: 20,  
        x: 50,  
        y: 50,  
        dx: 20,  
        dy: 10,  
        speed: 0.5,  
        bullets: [],  
        keyCooldown: 0  
    };  

    const bullets = []; // All bullets (both player & enemy)  
    const explosions = []; // Explosions  

    function spawnEnemies() {  
        enemy.grid = [];  
        for (let r = 0; r < enemy.rows; r++) {  
            const row = [];  
            for (let c = 0; c < enemy.cols; c++) {  
                row.push({  
                    x: enemy.x + c * (enemy.w + 10),  
                    y: enemy.y + r * (enemy.h + 10),  
                    w: enemy.w,  
                    h: enemy.h,  
                    alive: true  
                });  
            }  
            enemy.grid.push(row);  
        }  
    }  

    spawnEnemies();  

    function drawPlayer() {  
        ctx.fillStyle = '#0f0';  
        ctx.beginPath();  
        ctx.moveTo(player.x, player.y - player.h / 2);  
        ctx.lineTo(player.x - player.w / 2, player.y + player.h / 2);  
        ctx.lineTo(player.x + player.w / 2, player.y + player.h / 2);  
        ctx.closePath();  
        ctx.fill();  
    }  

    function drawEnemies() {  
        ctx.fillStyle = '#f00';  
        for (const row of enemy.grid) {  
            for (const e of row) {  
                if (e.alive) {  
                    ctx.fillRect(e.x - e.w / 2, e.y - e.h / 2, e.w, e.h);  
                }  
            }  
        }  
    }  

    function drawBullets() {  
        ctx.fillStyle = '#fff';  
        for (const b of bullets) {  
            ctx.fillRect(b.x - b.w / 2, b.y - b.h / 2, b.w, b.h);  
        }  
    }  

    function drawExplosions() {  
        for (const e of explosions) {  
            ctx.fillStyle = `rgba(255,${Math.floor(255 * e.alpha)},0,${e.alpha})`;  
            ctx.beginPath();  
            ctx.arc(e.x, e.y, e.size, 0, Math.PI * 2);  
            ctx.fill();  
        }  
    }  

    function drawHUD() {  
        ctx.fillStyle = '#fff';  
        ctx.font = '18px monospace';  
        ctx.fillText(`Score: ${score}  Level: ${level}`, 10, 20);  
    }  

    function updatePlayer() {  
        if (keys[KEY.LEFT] && player.x - player.w / 2 > 0) player.x -= player.speed;  
        if (keys[KEY.RIGHT] && player.x + player.w / 2 < WIDTH) player.x += player.speed;  

        if (keys[KEY.SPACE] && player.fireCooldown <= 0) {  
            bullets.push({  
                x: player.x,  
                y: player.y - player.h / 2,  
                w: 4,  
                h: 10,  
                dy: -8,  
                source: 'player'  
            });  
            player.fireCooldown = 15;  
        }  

        if (player.fireCooldown > 0) player.fireCooldown--;  
    }  

    function updateEnemies() {  
        // Move horizontally  
        enemy.x += enemy.dx * enemy.speed;  
        let hitEdge = false;  
        for (const row of enemy.grid) {  
            for (const e of row) {  
                if (e.alive) {  
                    const newX = e.x + enemy.dx * enemy.speed;  
                    if (newX - e.w / 2 < 0 || newX + e.w / 2 > WIDTH) {  
                        hitEdge = true; break;  
                    }  
                }  
            }  
            if (hitEdge) break;  
        }  
        if (hitEdge) {  
            enemy.dx *= -1;  
            enemy.y += enemy.dy;  
        }  

        // Enemy shooting  
        enemy.keyCooldown--;  
        if (enemy.keyCooldown <= 0) {  
            // Pick a random alive enemy  
            const alive = [];  
            for (const row of enemy.grid) {  
                for (const e of row) {  
                    if (e.alive) alive.push(e);  
                }  
            }  
            if (alive.length > 0) {  
                const shooter = alive[Math.floor(Math.random() * alive.length)];  
                bullets.push({  
                    x: shooter.x,  
                    y: shooter.y + shooter.h / 2,  
                    w: 4,  
                    h: 10,  
                    dy: 5,  
                    source: 'enemy'  
                });  
            }  
            enemy.keyCooldown = 200;  
        }  

        // Check if any enemy reached bottom → lose  
        for (const row of enemy.grid) {  
            for (const e of row) {  
                if (e.alive && e.y + e.h / 2 >= HEIGHT - 50) {  
                    gameOver = true;  
                }  
            }  
        }  
    }  

    function updateBullets() {  
        for (let i = bullets.length - 1; i >= 0; i--) {  
            const b = bullets[i];  
            b.y += b.dy;  
            // Remove off-screen bullets  
            if (b.y < 0 || b.y > HEIGHT) {  
                bullets.splice(i, 1);  
                continue;  
            }  
            // Collision detection  
            if (b.source === 'player') {  
                for (const row of enemy.grid) {  
                    for (const e of row) {  
                        if (e.alive && rectIntersect(b, e)) {  
                            e.alive = false;  
                            bullets.splice(i, 1);  
                            explosions.push({ x: e.x, y: e.y, size: 20, alpha: 1 });  
                            score += 10;  
                            break;  
                        }  
                    }  
                }  
            } else if (b.source === 'enemy') {  
                if (rectIntersect(b, player)) {  
                    bullets.splice(i, 1);  
                    explosions.push({ x: player.x, y: player.y, size: 30, alpha: 1 });  
                    gameOver = true;  
                    break;  
                }  
            }  
        }  
    }  

    function updateExplosions() {  
        for (let i = explosions.length - 1; i >= 0; i--) {  
            const e = explosions[i];  
            e.size += 2; e.alpha -= 0.03;  
            if (e.alpha <= 0) explosions.splice(i, 1);  
        }  
    }  

    function rectIntersect(a, b) {  
        return a.x + a.w / 2 > b.x - b.w / 2 &&  
               a.x - a.w / 2 < b.x + b.w / 2 &&  
               a.y + a.h / 2 > b.y - b.h / 2 &&  
               a.y - a.h / 2 < b.y + b.h / 2;  
    }  

    function checkLevelComplete() {  
        for (const row of enemy.grid) { for (const e of row) { if (e.alive) return; } }  
        level++;  
        enemy.speed += 0.2;  
        spawnEnemies();  
    }  

    function drawGameOver() {  
        ctx.fillStyle = 'rgba(0,0,0,0.5)';  
        ctx.fillRect(0,0,WIDTH,HEIGHT);  
        ctx.fillStyle = '#fff';  
        ctx.font = '36px monospace';  
        ctx.textAlign = 'center';  
        ctx.fillText('GAME OVER\nScore: ' + score, WIDTH/2, HEIGHT/2);  
    }  

    function loop() {  
        if (!gameOver) {  
            updatePlayer();  
            updateEnemies();  
            updateBullets();  
            updateExplosions();  
            checkLevelComplete();  

            // Draw  
            ctx.clearRect(0,0,WIDTH,HEIGHT);  
            drawPlayer();  
            drawEnemies();  
            drawBullets();  
            drawExplosions();  
            drawHUD();  

            requestAnimationFrame(loop);  
        } else {  
            drawGameOver();  
        }  
    }  

    loop();  
}

